/// JS: `canonicalEnvFlags(_input, _context)` — returns the canonical data, verbatim.
pub fn canonicalEnvFlags(_input: &Value, _context: &Value) -> Value {
    CANONICAL_ENV_FLAGS.clone()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn canonical_env_flags_parses_with_the_pressed_shape() {
        let v: &Value = &CANONICAL_ENV_FLAGS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 126, "pressed length (113 pressed + 7 context-pack flags + 3 CLI chat-engine flags, 2026-09-14/16; 2026-09-18: −3 Node-script paths +6 sidecar/goal-run flags)");
    }

    #[test]
    fn canonicalenvflags_returns_the_static_verbatim() {
        assert_eq!(canonicalEnvFlags(&Value::Null, &Value::Null), *CANONICAL_ENV_FLAGS);
    }

}
